import "./App.css";
import { useAuth } from "./context/auth-context";
import { AuthenticatedApp } from "./authenticated-app";
import { UnauthicatedAPP } from "./unauthenticated-app";
import { ErrorBoundary } from "./components/err-broudary";
import { FullPageErrorFallback } from "./components/lib";

function App() {
  const { user } = useAuth();
  return (
    <div className="App">
      <ErrorBoundary fallbackRender={FullPageErrorFallback}>
        {user ? <AuthenticatedApp /> : <UnauthicatedAPP />}
      </ErrorBoundary>
    </div>
  );
}

export default App;
