import { useEffect, useRef, useState } from "react";

// 全部可提取的类型，统一放在文件最上方

export const isFalsy = (value: unknown) => (value === 0 ? false : !value); //等于0就时true，不为0就取反
export const isVoid = (value: unknown) =>
  value === undefined || value === null || value === "";

export const cleanObject = (object: { [key: string]: unknown }) => {
  const result = { ...object };
  Object.keys(object).forEach((key: string) => {
    const value = result[key];
    if (isVoid(value)) {
      delete result[key];
    }
  });
  return result;
};

export const useMount = (callback: () => void) => {
  //定义callback必须是一个函数，不返回任何值
  //只在组件第一次挂载渲染完成后执行一次，组件重新渲染不会再执行
  useEffect(() => {
    callback();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
};

export const useDebounce = <V>(value: V, delay?: number) => {
  //当value频繁变化，不会立刻更新debounceValue,而是通知输入等待delay毫秒后才复制
  const [debounceValue, setDebounceValue] = useState(value);
  useEffect(() => {
    const timeout = setTimeout(() => setDebounceValue(value), delay);
    return () => clearTimeout(timeout); //负责清理上一次useEffect任务
  }, [value, delay]); //每次value变化时，都会设置一个定时器
  return debounceValue;
};

export const useDocumentTitle = (
  title: string,
  keepOnmount: boolean = true,
) => {
  const oldTitle = useRef(document.title).current; //页面加载时：旧title

  //加载后title变为新title
  useEffect(() => {
    document.title = title;
  }, [title]); //当title变化的时候

  useEffect(() => {
    return () => {
      if (!keepOnmount) {
        //如果不指定依赖，读到的就是旧title
        document.title = oldTitle;
      }
    };
  }, []); //当页面卸载的时候
};

export const restRoute = () => {
  window.location.href = window.location.origin;
};

export const subset = <
  O extends { [key in string]: unknown },
  K extends keyof O,
>(
  obj: O,
  keys: K[],
) => {
  const filteredEntries = Object.entries(obj).filter(([key]) =>
    keys.includes(key as K),
  );
  return Object.fromEntries(filteredEntries) as Pick<O, K>;
};

// 返回组件挂载状态，如果还没有挂载或者已经卸载，返回false；反之，返回true
export const useMountedRef = () => {
  const mountedRef = useRef(false);
  useEffect(() => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  });
  return mountedRef;
};
